(()=>{'use strict';
 const D=WhData,R=WhRules,$=id=>document.getElementById(id),params=new URLSearchParams(location.search),method=params.get('method')==='immediate'?'immediate':'wait';
 const key='dijitalErkenEgitim5N1KResultsV1',rewards=['Aferin!','Harikasın!','Çok güzel!','Bravo!','Süpersin!','Çok iyi yaptın!','Başardın!','Ne güzel yaptın!','Harika bir cevap!','Çok dikkatliydin!','Tebrik ederim!','Şahane!','Çok güzel ilerliyorsun!'];
 let level=1,storyIndex=0,questionIndex=0,input='voice',phase='setup',generation=0,timer=null,rec=null,busy=false,paused=false,prompted=false,misses=0,attempts=[],firstResponse=null,recorded=false,runId='',records=[],returnSection='setup',micReady=false,starting=false,videoReplay=false;
 const learner=(()=>{try{const p=JSON.parse(localStorage.getItem('dijitalOzelEgitimStateV2'))?.profile;const value=(p?.name||'cihaz')+'|'+(p?.age||'');let h=2166136261;for(const ch of value)h=Math.imul(h^ch.charCodeAt(0),16777619);return 'learner-'+(h>>>0).toString(16);}catch{return 'learner-device';}})();
 try{records=JSON.parse(localStorage.getItem(key))||[];if(!Array.isArray(records))records=[];}catch{records=[];}
 const current=()=>D.stories.find(s=>s.id===D.levels[level-1].stories[storyIndex]),question=()=>current().questions[questionIndex];
 const canReport=()=>{try{return parent===window?params.get('role')!=='child':parent.ParentGate?.role()==='guardian';}catch{return false;}};
 const active=()=>!paused&&!$('work').hidden,clearTimer=()=>{clearTimeout(timer);timer=null;};
 function stopRec(){const old=rec;rec=null;if(old){old.onresult=old.onend=old.onerror=old.onstart=old.onspeechstart=old.onprocessing=null;old.abort();}}
 function clear(){clearTimer();stopRec();}
 function cancel(){generation++;clear();speechSynthesis.cancel();busy=false;}
 function controls(disabled){document.querySelectorAll('#answers button').forEach(b=>b.disabled=disabled);$('help').disabled=disabled;$('replay').disabled=disabled;}
 function show(id){for(const x of ['setup','work','storyEnd','levelEnd','report'])$(x).hidden=x!==id;$('pause').hidden=id!=='work';$('reportOpen').hidden=!canReport()||id==='report';}
 function say(text,done){clear();busy=true;controls(true);$('feedback').textContent=text;const g=generation,u=new SpeechSynthesisUtterance(text);u.lang='tr-TR';u.onend=()=>{if(g!==generation||paused)return;busy=false;controls(false);done?.();};u.onerror=()=>{if(g!==generation)return;busy=false;controls(false);$('feedback').textContent='Seslendirme tamamlanamadı. Yeniden dinle.';$('listenAgain').hidden=false;};speechSynthesis.speak(u);}
 function setup(){cancel();$('video').pause();phase='setup';document.body.dataset.phase=phase;show('setup');$('methodLabel').textContent=method==='immediate'?'Eşzamanlı öğretim':'4 saniye sabit bekleme süreli öğretim';$('levels').replaceChildren();D.levels.forEach(s=>{const b=document.createElement('button');b.innerHTML=`<strong>${s.number}</strong><span>${s.title}<small>5 olay · her olayda 6 soru</small></span>`;b.onclick=()=>start(s.number);$('levels').append(b);});setMode(input);}
 function setMode(mode){input=mode;for(const [id,value] of [['voiceMode','voice'],['choiceMode','choice']])$(id).setAttribute('aria-pressed',String(input===value));$('setupStatus').textContent='';}
 async function start(n){if(starting)return;starting=true;try{if(input==='voice'&&!micReady){$('setupStatus').textContent='Dinleme hazırlanıyor…';await LocalMicrophone.ensure();const response=await fetch('/api/status');const status=await response.json();if(!response.ok||!status.ready)throw Error(status.message||'Dinleme hazır değil.');micReady=true;}level=n;storyIndex=0;questionIndex=0;runId=crypto.randomUUID();watch(false);}catch(error){$('setupStatus').textContent='Dinleme açılamadı. '+error.message+' Seç ile de çalışabilirsin.';}finally{starting=false;}}
 function watch(replay){videoReplay=replay;cancel();paused=false;phase='video';document.body.dataset.phase=phase;show('work');$('pause').textContent='Mola';$('questionArea').hidden=true;$('play').hidden=true;$('listenAgain').hidden=true;const s=current();$('counter').textContent=`Seviye ${level} · Olay ${storyIndex+1} / 5`;
  const v=$('video');v.src=s.video;v.poster=s.poster;v.currentTime=0;v.onended=()=>{if(!active()||phase!=='video')return;phase='narration';$('questionArea').hidden=false;$('question').textContent='';$('answers').hidden=true;const g=generation;say(s.narration,()=>{if(g===generation){if(!replay){questionIndex=0;newQuestion();}else ask();}});};
  v.onerror=()=>{if(!active())return;$('play').hidden=false;$('play').textContent='Videoyu yeniden yükle';$('play').onclick=()=>watch(replay);};v.play().catch(()=>{$('play').hidden=false;$('play').textContent='▶ İzle';$('play').onclick=()=>v.play().then(()=>$('play').hidden=true).catch(()=>$('feedback').textContent='Video başlatılamadı.');});
 }
 function optionArt(container,s,q,value){const other=D.stories.find(x=>x.id===value.story)||s;
  if(q.type==='nerede'){const img=document.createElement('img');img.src=`assets/5n1k/backgrounds/${other.place}.webp`;img.alt='';container.append(img);return;}
  const c=document.createElement('canvas');c.width=240;c.height=180;const ctx=c.getContext('2d');ctx.fillStyle='#f1f6f7';ctx.fillRect(0,0,240,180);
  if(q.type==='ne')WhScene.prop(ctx,value.answer,120,90,2.3);
  else if(q.type==='kim'){ctx.save();ctx.scale(.68,.68);WhScene.child(ctx,175,252,other.palette,[135,170],[215,170]);ctx.restore();}
  else if(q.type==='ne zaman'){ctx.fillStyle=value.answer==='akşam'?'#536483':'#c9e8f1';ctx.fillRect(0,0,240,180);ctx.beginPath();ctx.arc(120,value.answer==='sabah'?112:68,29,0,Math.PI*2);ctx.fillStyle=value.answer==='akşam'?'#fff0b0':'#f2c853';ctx.fill();}
  else{const img=document.createElement('img');img.src=other.poster;img.alt='';container.append(img);return;}container.append(c);
 }
 function renderAnswers(){const s=current(),q=question(),values=R.choices(s,q),area=$('answers');area.hidden=input!=='choice';area.style.setProperty('--choices',values.length);area.replaceChildren();values.forEach(value=>{const wrapper=document.createElement('div');wrapper.className='answer';const b=document.createElement('button');b.type='button';b.dataset.answer=value.answer;b.setAttribute('aria-label',value.answer);optionArt(b,s,q,value);const span=document.createElement('span');span.textContent=value.answer;b.append(span);b.onclick=()=>answer(value.answer,'choice');const audio=document.createElement('button');audio.type='button';audio.className='speak-option';audio.textContent='🔊 Dinle';audio.setAttribute('aria-label',value.answer+' seçeneğini dinle');audio.onclick=()=>{if(busy||recorded||paused)return;prompted=true;firstResponse??='option-help';say(value.answer,()=>response());};wrapper.append(b,audio);area.append(wrapper);});}
 function newQuestion(){prompted=false;misses=0;attempts=[];firstResponse=null;recorded=false;renderAnswers();ask();}
 function ask(){cancel();phase='question';document.body.dataset.phase=phase;$('questionArea').hidden=false;$('question').textContent=question().text;$('counter').textContent=`Seviye ${level} · Olay ${storyIndex+1} / 5 · Soru ${questionIndex+1} / 6`;$('listenAgain').hidden=true;controls(true);say(question().text,()=>{if(method==='immediate'||prompted)hint();else response();});}
 function response(){if(!active()||recorded)return;phase='response';controls(false);if(input==='voice'){listen();return;}$('feedback').textContent=prompted?'Şimdi seç.':'';if(!prompted)timer=setTimeout(()=>failure('no-response'),4000);}
 function hint(){if(!active()||recorded)return;clear();prompted=true;phase='prompt';document.querySelectorAll('#answers [data-answer]').forEach(b=>b.classList.toggle('hint',b.dataset.answer===question().answer));say(question().evidence+(input==='voice'?' Şimdi sen söyle.':' Şimdi seç.'),response);if(input==='choice'){busy=false;phase='response';controls(false);}}
 function answer(text,source){if(!active()||busy||recorded||phase!=='response')return;clear();const verdict=R.judge(text,question());if(verdict==='correct'){attempts.push('correct');firstResponse??='correct';finish(prompted||misses?'prompted':'independent',source);}else failure(verdict==='uncertain'?'no-response':verdict,source);}
 function failure(kind,source=input){if(!active()||busy||recorded)return;clear();attempts.push(kind);firstResponse??=kind;misses++;prompted=true;const safe=kind==='inappropriate'?'Bu söylediğin sözcük uygun bir sözcük değil. ':'';
  if(misses>=2){const outcome=attempts.every(x=>x==='no-response')?'no-response':'incorrect';save(outcome,source);say(safe+question().evidence,advanceQuestion);}
  else{document.querySelectorAll('#answers [data-answer]').forEach(b=>b.classList.toggle('hint',b.dataset.answer===question().answer));say(safe+question().evidence+(input==='voice'?' Şimdi sen söyle.':' Şimdi seç.'),response);}
 }
 function save(outcome,source){if(recorded)return;recorded=true;records.push({runId,learner,storyId:current().id,level,story:storyIndex+1,type:question().type,question:questionIndex+1,method,input:source,outcome,firstResponse,attempts:[...attempts],time:new Date().toISOString()});try{localStorage.setItem(key,JSON.stringify(records));}catch{$('feedback').textContent='Sonuç bu tarayıcıda saklanamadı. Sonuçları indirerek koruyabilirsiniz.';}}
 function finish(outcome,source){save(outcome,source);document.querySelectorAll('#answers [data-answer]').forEach(b=>b.classList.toggle('good',b.dataset.answer===question().answer));say(rewards[Math.floor(Math.random()*rewards.length)],advanceQuestion);}
 function advanceQuestion(){phase='reward';const g=generation;timer=setTimeout(()=>{if(g!==generation||!active())return;questionIndex++;if(questionIndex<6)newQuestion();else endStory();},700);}
 function technical(message){clear();$('feedback').textContent=message+' Yeniden dinle ile tekrar dene.';$('listenAgain').hidden=false;controls(false);phase='technical';}
 function listen(){clear();if(!active()||recorded)return;phase='response';const g=generation,r=new LocalSpeechRecognition();r.domain='wh';rec=r;let spoke=false;const valid=()=>g===generation&&rec===r&&active();
  r.onstart=()=>{if(!valid())return;$('feedback').textContent='Dinliyorum…';timer=setTimeout(()=>{if(valid()&&!spoke)failure('no-response');},prompted?8000:4000);};
  r.onspeechstart=()=>{if(!valid()||spoke)return;spoke=true;clearTimer();timer=setTimeout(()=>{if(valid())technical('Yanıt çözümlenemedi.');},30000);};
  r.onprocessing=()=>{if(!valid())return;clearTimer();$('feedback').textContent='Yanıt çözümleniyor…';timer=setTimeout(()=>{if(valid())technical('Dinleme hizmeti yanıt vermedi.');},30000);};
  r.onresult=e=>{if(!valid())return;const result=e.results[e.resultIndex];if(!result?.isFinal)return;const text=result[0].transcript;if(!NamingRules.normalize(text)){technical('Söyleyiş anlaşılamadı.');return;}answer(text,'voice');};r.onerror=()=>{if(valid())technical('Mikrofon veya dinleme bağlantısı çalışmadı.');};r.onend=()=>{if(valid())technical('Net yanıt alınamadı.');};r.start();
 }
 function runRows(){return records.filter(r=>r.runId===runId);}
 function endStory(){cancel();phase='storyEnd';show('storyEnd');const rows=runRows().filter(r=>r.storyId===current().id);$('storyTotal').textContent=`${rows.filter(r=>r.outcome==='independent').length} bağımsız doğru · ${rows.filter(r=>r.outcome==='prompted').length} ipucuyla doğru`;if(storyIndex===4){phase='levelEnd';show('levelEnd');$('levelTotal').textContent='5 olay ve 30 soru tamamlandı.';$('nextLevel').hidden=level===10;$('gameNote').hidden=true;const rows=runRows(),stats={independent:rows.filter(r=>r.outcome==='independent').length,prompted:rows.filter(r=>r.outcome==='prompted').length,incorrect:rows.filter(r=>['incorrect','no-response'].includes(r.outcome)).length};if(parent!==window)parent.postMessage({type:'wh-teaching-complete',level,stats},location.origin);}}
 function menu(){cancel();$('video').pause();if(parent!==window)parent.postMessage({type:'wh-teaching-menu'},location.origin);else location.href='./';}
 function report(){if(!canReport())return;returnSection=['setup','storyEnd','levelEnd'].find(id=>!$(id).hidden)||'setup';cancel();$('video').pause();show('report');const rows=records.filter(r=>r.learner===learner);$('reportRows').innerHTML=R.totals(rows).map(r=>`<tr><td>${r.type}</td><td>${r.independent}</td><td>${r.prompted}</td><td>${r.incorrect}</td><td>${r.noResponse}</td></tr>`).join('');$('reportDetail').replaceChildren();for(const r of rows.slice(-300)){const a=document.createElement('article');const names={independent:'Bağımsız doğru',prompted:'İpucuyla doğru',incorrect:'Yanlış','no-response':'Yanıtsız'};a.textContent=`Seviye ${r.level} · Olay ${r.story} · ${r.type}: ${names[r.outcome]} · İlk tepki: ${{correct:'doğru',wrong:'yanlış','no-response':'yanıtsız',inappropriate:'uygun olmayan sözcük',help:'ipucu istendi','option-help':'seçenek dinlendi'}[r.firstResponse]||'ipucu sonrası'} · ${r.input==='voice'?'sesli':'seçerek'} · ${r.attempts.length} yanıt`; $('reportDetail').append(a);}}
 function exportResults(){if(!canReport())return;const rows=records.filter(r=>r.learner===learner),fields=['time','runId','level','storyId','type','method','input','outcome','firstResponse','attempts'];const quote=v=>'"'+String(Array.isArray(v)?v.join('|'):v??'').replaceAll('"','""')+'"';const csv='\ufeff'+[fields.join(';'),...rows.map(r=>fields.map(k=>quote(r[k])).join(';'))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='5N1K-sonuclar.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('voiceMode').onclick=()=>setMode('voice');$('choiceMode').onclick=()=>setMode('choice');$('menu').onclick=$('endMenu').onclick=menu;$('nextStory').onclick=()=>{storyIndex++;questionIndex=0;watch(false);};$('nextLevel').onclick=()=>start(level+1);$('game').onclick=()=>$('gameNote').hidden=false;
 $('help').onclick=()=>{if(active()&&!busy&&!recorded){firstResponse??='help';hint();}};$('replay').onclick=()=>{if(!busy&&!recorded){prompted=true;firstResponse??='help';watch(true);}};$('listenAgain').onclick=()=>{if(!busy&&active()&&!recorded){$('listenAgain').hidden=true;ask();}};
 $('reportOpen').onclick=report;$('reportBack').onclick=()=>show(returnSection);$('export').onclick=exportResults;
 $('pause').onclick=()=>{if(paused){paused=false;$('pause').textContent='Mola';if(recorded)advanceQuestion();else if(phase==='video'){$('video').play().catch(()=>$('play').hidden=false);}else if(phase==='narration')say(current().narration,()=>{if(videoReplay)ask();else{questionIndex=0;newQuestion();}});else ask();}else{paused=true;cancel();$('video').pause();$('pause').textContent='Devam et';$('feedback').textContent='Mola.';}};
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&active())$('pause').click();});window.addEventListener('pagehide',()=>{cancel();$('video').pause();});setup();
})();
